'use client'

import { motion, useInView } from 'motion/react'
import { useRef } from 'react'
import { fadeUp, staggerContainer, revealViewport, motionTokens } from '@/lib/motion'

const leaks = [
  {
    text: 'Tareas manuales repetidas que ya podrían estar ',
    bold: 'automatizadas',
  },
  {
    text: 'Reportes armados a mano que ',
    bold: 'llegan tarde',
    text2: ' a la decisión.',
  },
  {
    text: 'Capacidad instalada ',
    bold: 'ociosa',
    text2: ' por cuellos de botella no medidos.',
  },
  {
    text: 'Decisiones gerenciales con ',
    bold: 'datos desactualizados',
    text2: '.',
  },
]

export function Problem() {
  const containerRef = useRef(null)
  const isInView = useInView(containerRef, { once: true, amount: 0.25 })

  return (
    <section id="problema" className="bg-[#221B31] py-16 md:py-24">
      <div className="max-w-6xl mx-auto px-6 md:px-8">
        <motion.div
          ref={containerRef}
          initial="hidden"
          animate={isInView ? 'show' : 'hidden'}
          variants={staggerContainer(motionTokens.stagger.base, 0)}
          viewport={revealViewport}
          className="grid md:grid-cols-2 gap-12 md:gap-16"
        >
          {/* Left column - kicker and statement */}
          <motion.div variants={fadeUp}>
            <div className="inline-flex items-center gap-3 mb-6">
              <span className="w-8 h-0.5 bg-[#E07B30]" />
              <span className="font-mono text-xs font-bold uppercase tracking-widest text-[#E07B30]">
                El problema
              </span>
            </div>
            <h2 className="font-serif text-4xl md:text-5xl font-bold leading-tight">
              Tu negocio crece. Y aun así,{' '}
              <em className="italic text-[#E07B30]">pierde dinero</em>.
            </h2>
          </motion.div>

          {/* Right column - body text + leaks */}
          <motion.div variants={fadeUp} className="space-y-6">
            {/* Body paragraphs */}
            <div className="space-y-3">
              <p className="text-base md:text-lg text-white font-semibold">
                Hay procesos que nadie mide. Ahí se escapa el margen.
              </p>
              <p className="text-base md:text-lg text-gray-300 leading-relaxed">
                La <strong className="text-white font-semibold">fuga de valor</strong> no aparece en
                el estado de resultados. Aparece en horas perdidas, reprocesos, capacidad ociosa y
                decisiones tomadas a ciegas.
              </p>
              <p className="text-base md:text-lg text-gray-300 leading-relaxed">
                No la cerramos con otro tablero. La cerramos midiendo dónde se pierde —y cuánto
                cuesta en plata.
              </p>
            </div>

            {/* Leaks List */}
            <div className="space-y-0 mt-8">
              {leaks.map((leak, idx) => (
                <motion.div
                  key={idx}
                  initial={{ opacity: 0, x: -motionTokens.distance.md }}
                  animate={isInView ? { opacity: 1, x: 0 } : { opacity: 0, x: -motionTokens.distance.md }}
                  transition={{
                    duration: motionTokens.duration.base,
                    ease: motionTokens.ease.out,
                    delay: isInView ? 0.2 + idx * motionTokens.stagger.tight : 0,
                  }}
                  className="flex gap-4 items-start py-4 px-4 border-t border-white/10 first:border-t-0"
                >
                  <span className="font-mono text-sm text-[#E07B30] font-bold flex-none">
                    {String(idx + 1).padStart(2, '0')}
                  </span>
                  <span className="text-gray-300 text-sm leading-relaxed">
                    {leak.text}
                    <strong className="text-white font-semibold">{leak.bold}</strong>
                    {leak.text2}
                  </span>
                </motion.div>
              ))}
            </div>
          </motion.div>
        </motion.div>
      </div>
    </section>
  )
}
