'use client'

import { motion, useInView } from 'motion/react'
import { useRef } from 'react'
import { ArrowRight } from 'lucide-react'
import { fadeUp, staggerContainer, methodologyContainer, revealViewport, motionTokens } from '@/lib/motion'

const steps = [
  {
    num: '01',
    title: 'Investigación',
    description: 'Vamos a tu operación. Observamos el proceso real, no el del manual.',
  },
  {
    num: '02',
    title: 'Diagnóstico',
    description: 'Medimos dónde se fuga el valor y cuánto cuesta, en plata.',
  },
  {
    num: '03',
    title: 'Propuesta',
    description: 'Diseñamos la solución y proyectamos el retorno antes de ejecutar.',
  },
  {
    num: '04',
    title: 'Implementación',
    description: 'Ejecutamos, medimos el resultado y lo dejamos operando.',
  },
]

const frameworks = [
  'Toyota Production System',
  'Teoría de Restricciones',
  'Lean Six Sigma',
  'CMMI',
]

export function Methodology() {
  const containerRef = useRef(null)
  const isInView = useInView(containerRef, { once: true, amount: 0.25 })

  return (
    <section id="metodologia" className="bg-[#221B31] py-16 md:py-24">
      <div className="max-w-6xl mx-auto px-6 md:px-8">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: motionTokens.distance.md }}
          animate={isInView ? { opacity: 1, y: 0 } : { opacity: 0, y: motionTokens.distance.md }}
          transition={{
            duration: motionTokens.duration.base,
            ease: motionTokens.ease.out,
          }}
          className="max-w-2xl mb-16"
        >
          <div className="inline-flex items-center gap-3 mb-6">
            <span className="w-8 h-0.5 bg-[#E07B30]" />
            <span className="font-mono text-xs font-bold uppercase tracking-widest text-[#E07B30]">
              Metodología
            </span>
          </div>
          <h2 className="font-serif text-4xl md:text-5xl font-bold leading-tight mb-4">
            De la observación al <em className="italic text-[#E07B30]">resultado operando</em>.
          </h2>
          <p className="text-lg text-gray-400">
            Un método de ingeniería de producción, no de consultoría de PowerPoint. Cuatro pasos, cada
            uno con su entregable.
          </p>
        </motion.div>

        {/* Steps Flow */}
        <motion.div
          ref={containerRef}
          className="grid md:grid-cols-4 gap-0 mb-16"
          initial="hidden"
          animate={isInView ? 'show' : 'hidden'}
          variants={methodologyContainer}
          viewport={revealViewport}
        >
          {steps.map((step, idx) => (
            <motion.div
              key={idx}
              variants={{
                hidden: { opacity: 0, y: motionTokens.distance.md },
                show: {
                  opacity: 1,
                  y: 0,
                  transition: {
                    duration: motionTokens.duration.base,
                    ease: motionTokens.ease.out,
                  },
                },
              }}
              className={`relative p-6 md:p-8 ${
                idx !== steps.length - 1 ? 'border-r border-white/10 pr-8 md:pr-10' : ''
              } ${idx !== 0 ? 'pl-8 md:pl-10' : ''}`}
            >
              {/* Number label */}
              <span className="font-mono text-xs font-bold uppercase tracking-widest text-[#E07B30] block mb-2">
                {step.num}
              </span>

              {/* Large background number */}
              <span className="absolute top-4 left-0 right-0 font-serif text-7xl md:text-8xl font-bold text-white/10 -z-10">
                {step.num}
              </span>

              {/* Arrow */}
              {idx !== steps.length - 1 && (
                <div className="absolute -right-6 top-12 md:top-16">
                  <ArrowRight className="w-4 h-4 text-[#E07B30]" />
                </div>
              )}

              {/* Title */}
              <h4 className="font-serif text-2xl font-bold mb-3">{step.title}</h4>

              {/* Description */}
              <p className="text-gray-400 text-sm leading-relaxed">{step.description}</p>
            </motion.div>
          ))}
        </motion.div>

        {/* Frameworks */}
        <motion.div
          initial={{ opacity: 0, y: motionTokens.distance.md }}
          animate={isInView ? { opacity: 1, y: 0 } : { opacity: 0, y: motionTokens.distance.md }}
          transition={{
            duration: motionTokens.duration.base,
            ease: motionTokens.ease.out,
            delay: 0.3,
          }}
          className="flex flex-wrap items-center gap-3"
        >
          <span className="font-mono text-xs font-bold uppercase tracking-widest text-gray-500">
            Marco metodológico
          </span>
          {frameworks.map((fw, idx) => (
            <motion.div
              key={idx}
              initial={{ opacity: 0, scale: 0.95 }}
              animate={isInView ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0.95 }}
              transition={{
                duration: motionTokens.duration.base,
                ease: motionTokens.ease.out,
                delay: 0.4 + idx * motionTokens.stagger.tight,
              }}
              className="font-mono text-xs font-medium uppercase tracking-widest px-4 py-2 border border-white/20 rounded-lg text-gray-400 hover:text-white hover:border-white/40 transition-all"
            >
              {fw}
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  )
}
