'use client'

import { motion, useInView } from 'motion/react'
import { useRef } from 'react'
import {
  fadeUp,
  fadeUpSm,
  scaleIn,
  staggerContainer,
  revealViewport,
  useCountUp,
  motionTokens,
  cardHover,
} from '@/lib/motion'

export function Results() {
  const containerRef = useRef(null)
  const isInView = useInView(containerRef, { once: true, amount: 0.25 })

  const { ref: ref1, display: display1 } = useCountUp(34, { suffix: '%' })
  const { ref: ref2, display: display2 } = useCountUp(28, { suffix: '%' })

  const cases = [
    {
      tag: 'Spa & Belleza',
      result: ref1,
      display: display1,
      label: 'tiempo de agendamiento',
      description:
        'Automatizamos la reserva y la reportería diaria. El equipo dejó de armar Excel a mano cada noche y la ocupación subió sin contratar.',
      prefix: '−',
    },
    {
      tag: 'Sector Educativo',
      result: ref2,
      display: display2,
      label: 'capacidad utilizada',
      description:
        'Medimos la ocupación real de aulas y docentes. Se reasignó la capacidad ociosa detectada, sin ampliar la planta.',
      prefix: '+',
    },
  ]

  return (
    <section id="resultados" className="bg-[#2E2640] py-16 md:py-24">
      <div className="max-w-6xl mx-auto px-6 md:px-8">
        {/* Big Quote */}
        <motion.div
          ref={containerRef}
          initial="hidden"
          animate={isInView ? 'show' : 'hidden'}
          variants={staggerContainer(motionTokens.stagger.base, 0)}
          viewport={revealViewport}
          className="max-w-3xl mx-auto text-center mb-16"
        >
          <motion.div variants={fadeUpSm} className="inline-flex items-center gap-3 mb-8">
            <span className="w-8 h-0.5 bg-[#E07B30]" />
            <span className="font-mono text-xs font-bold uppercase tracking-widest text-[#E07B30]">
              Resultados
            </span>
            <span className="w-8 h-0.5 bg-[#E07B30]" />
          </motion.div>

          <motion.blockquote
            variants={fadeUp}
            className="font-serif text-3xl md:text-5xl font-bold leading-tight mb-6"
          >
            "Dejamos de discutir opiniones. Ahora discutimos{' '}
            <em className="italic text-[#E07B30]">números</em> — y las reuniones duran la mitad."
          </motion.blockquote>

          <motion.div variants={fadeUpSm} className="font-mono text-sm uppercase tracking-widest text-gray-500">
            Gerente de Operaciones · Cliente Yeti BI
          </motion.div>
        </motion.div>

        {/* Cases Grid */}
        <motion.div
          className="grid md:grid-cols-2 gap-6"
          initial="hidden"
          animate={isInView ? 'show' : 'hidden'}
          variants={staggerContainer(motionTokens.stagger.base, 0.2)}
          viewport={revealViewport}
        >
          {cases.map((caseItem, idx) => (
            <motion.div
              key={idx}
              variants={scaleIn}
              className="bg-[#372E4D] border border-white/10 rounded-2xl p-8"
              {...cardHover}
            >
              <div className="font-mono text-xs font-bold uppercase tracking-widest text-gray-500 mb-4">
                {caseItem.tag}
              </div>

              <div className="flex items-baseline gap-2 mb-3">
                <span className="font-mono text-sm text-[#E07B30] font-bold">{caseItem.prefix}</span>
                <span ref={caseItem.result} className="font-serif text-5xl md:text-6xl font-bold text-[#E07B30]">
                  {caseItem.display}
                </span>
              </div>

              <p className="text-white font-semibold text-lg mb-4">{caseItem.label}</p>
              <p className="text-gray-400 leading-relaxed text-sm">{caseItem.description}</p>
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  )
}
